-- =============================================================================
-- 风驰思维 · 教学管理系统  06 课时教案与师资团队
-- 依据机构提供的《课程体系图》《宣传册》《F2L/OLL/PLL 练习手册》整理。
-- 幂等：仅在该课程尚无课时、或该教练尚无记录时写入。
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. 课时教案
-- -----------------------------------------------------------------------------
insert into public.course_lessons (course_id, title, goal, content, formula, homework, order_index, duration_minutes)
select c.id, v.title, v.goal, v.content, v.formula, v.homework, v.order_index, v.duration_minutes
from (values
  -- 趣味启蒙魔方
  ('cube-enlighten', '六个面，六种颜色', '准确说出并快速指出六个面的颜色，记住对面关系', E'1. 认识白、黄、红、橙、蓝、绿六种颜色。\n2. 记住对面关系：白对黄、红对橙、蓝对绿。\n3. 游戏：老师报颜色，孩子快速用手指出来。', '—', '和爸爸妈妈玩「报颜色」游戏，看谁反应快', 1, 40),
  ('cube-enlighten', '认识中心块与棱块', '能区分中心块和棱块，理解中心块不会移动', E'1. 找出每个面正中间的方块。\n2. 转动魔方，观察中心块始终在自己那一面。\n3. 摸一摸棱块，数一数它有几个颜色。', '—', '数一数魔方一共有多少个方块', 2, 40),
  ('cube-enlighten', '我的第一转：R 和 R''', '听懂并完成右手面顺时针、逆时针转动', E'1. 学习标准握法：左手拇指在前，右手拇指在后。\n2. 练习右手面顺时针转 90 度（R）。\n3. 练习逆时针转 90 度（R''）。\n4. 游戏：听指令转动，看谁不出错。', 'R / R''', '练习 R 和 R'' 各 20 次', 3, 40),
  ('cube-enlighten', '转一转：U 和 D', '掌握顶面与底面的转动指令', E'1. 学习 U（顶面顺时针）与 U''（逆时针）。\n2. 学习 D（底面顺时针）与 D''。\n3. 组合练习：U R U'' R''。', 'U / U'' / D / D''', '练习 U R U'' R'' 连续 10 次', 4, 40),
  ('cube-enlighten', '颜色配对小游戏', '用学过的转动指令，把同色块凑到同一个面', E'1. 老师给出目标：让某个面出现两个同色块。\n2. 孩子尝试用学过的指令完成。\n3. 分享自己是怎么想的。', 'R / U / L / D 组合', '和爸爸妈妈比赛，看谁先把一面凑出三个同色块', 5, 40),
  ('cube-enlighten', '我的小成果展示', '独立完成一次「一面同色」，并讲出自己用了哪些转动', E'1. 复习所有学过的指令。\n2. 独立挑战「一面同色」。\n3. 上台展示，说出自己的思考过程。', '综合', '回家表演给家人看', 6, 40),

  -- 基础三阶魔方（箭头图示法）
  ('cube-basic', '认识三阶魔方与箭头图示', '看懂箭头图示，掌握标准握法与基本转动记号', E'1. 认识三阶魔方的中心块、棱块、角块。\n2. 学习转动记号：R L U D F B 及其带撇（逆时针）与数字 2（转两次）。\n3. 学会看箭头图示：箭头方向代表转动方向，箭头所在面代表转动的面。', '—', '按图示完成 10 组单层转动', 1, 45),
  ('cube-basic', '底层白色十字', '独立完成白色十字，且侧面颜色与中心块对齐', E'1. 找到白色中心块所在面，作为底面。\n2. 把四个带白色的棱块逐个转到顶面。\n3. 翻转到底面，让白色朝下。\n4. 检查侧面颜色是否与相邻中心块一致，不一致就调整。', 'R U R'' U''（调整棱块位置）', '连续做 5 次白色十字，每次侧面颜色都要对齐', 2, 45),
  ('cube-basic', '底层角块归位', '四个白色角块全部归位，完成整个底层', E'1. 在顶层找到带白色的角块。\n2. 把角块转到它目标位置的正上方。\n3. 用「右手公式」反复执行，直到角块落入底层。\n4. 口诀：白朝前用 R U R'' U''，白朝右用 U R U'' R''。', 'R U R'' U''', '独立完成底层，记录第一次用时', 3, 45),
  ('cube-basic', '中层棱块归位', '完成中间层四个棱块，前两层复原完成', E'1. 在顶层寻找不带黄色的棱块。\n2. 判断它应该去左边还是右边。\n3. 用左手公式或右手公式插入中层。\n4. 遇到卡在错误位置的棱块，先用公式把它顶出来再重做。', 'U R U'' R'' U'' F'' U F', '完成前两层复原，记录用时', 4, 45),
  ('cube-basic', '顶层黄色十字', '在顶面形成黄色十字（不要求角块位置正确）', E'1. 观察顶面黄色块的形状：点、一字、拐角、十字。\n2. 记住公式要从不同起始状态执行。\n3. 点 → 一字 → 拐角 → 十字，最多执行三次公式。', 'F R U R'' U'' F''', '把顶层黄色十字反复练习 10 次', 5, 45),
  ('cube-basic', '顶层角块朝向', '顶面四个角块颜色全部朝上', E'1. 找到顶面已经朝上的黄色角块，放在右前位置。\n2. 反复执行右手公式，直到该角块黄色朝上。\n3. 转动顶层 U，处理下一个角块。\n4. 注意：这个阶段魔方看起来会「更乱」，属正常现象，不要中途放弃。', 'R U R'' U''（重复 2 或 4 次）', '完成顶面全黄', 6, 45),
  ('cube-basic', '顶层棱块归位', '调整顶层棱块顺序，完成完整还原', E'1. 找一条已经对齐的「完整边」放在背面。\n2. 观察剩下三个棱块需要顺时针还是逆时针换位。\n3. 执行对应公式，魔方完成还原。', '顺时针 R U'' R U R U R U'' R'' U'' R2', '完成 3 次完整还原，取平均成绩', 7, 45),
  ('cube-basic', '综合练习与结课测评', '独立完成完整还原，平均成绩稳定在 2 分钟以内', E'1. 全流程串讲，梳理每一步的判断依据。\n2. 集中练习薄弱环节。\n3. 结课测评：连续 3 次还原取平均。\n4. 登记成绩并制定下一步学习计划。', '全部公式综合运用', '每天完成 3 次还原，下次课带成绩来', 8, 45),

  -- 进阶魔方
  ('cube-advanced', '二阶魔方：三阶的简化版', '理解二阶是三阶去掉中心块与棱块，能直接套用底层与顶层思路', E'1. 对比二阶与三阶的结构差异。\n2. 用三阶的角块公式完成二阶复原。\n3. 总结：哪些公式可以直接迁移，哪些需要调整。', 'R U R'' U''', '独立复原二阶魔方 3 次', 1, 45),
  ('cube-advanced', '金字塔魔方：转面与转角', '掌握金字塔魔方的基本转动与复原流程', E'1. 认识金字塔的四个面与三种块。\n2. 学习转面（大角）与转角（小角）的区别。\n3. 完成金字塔复原。', 'R U R'' U''', '独立复原金字塔 3 次', 2, 45),
  ('cube-advanced', '斜转魔方：转动轴的变化', '理解斜转魔方的转动轴与三阶不同，掌握其复原方法', E'1. 观察斜转魔方的轴与转动方式。\n2. 学习底层与顶层的处理顺序。\n3. 独立完成复原。', 'R L'' U'' R'' L', '独立复原斜转魔方 3 次', 3, 45),
  ('cube-advanced', '五魔方：多面体的解法迁移', '理解五魔方是「十二面的三阶」，能迁移已知思路', E'1. 认识五魔方的面、棱、角结构。\n2. 找到与三阶对应的部分。\n3. 分阶段完成复原。', '沿用三阶棱角处理思路', '完成五魔方的底层与中层', 4, 45),
  ('cube-advanced', 'SQ1 与镜面魔方初探', '了解不同变形魔方的判断依据：从形状而非颜色入手', E'1. 镜面魔方：用「大小」代替「颜色」判断位置。\n2. SQ1：观察转动后形状的变化规律。\n3. 尝试完成基础步骤。', '—', '尝试复原镜面魔方一面', 5, 45),
  ('cube-advanced', '异形魔方综合挑战', '综合运用迁移思维，独立解决一个没学过的新魔方', E'1. 老师给出一个没讲过的魔方。\n2. 学生先观察结构，说出自己的判断。\n3. 尝试用已有思路解决，老师只在卡住时点拨。', '迁移运用', '选一个喜欢的异形魔方带到下节课分享', 6, 45),

  -- 提速三阶魔方（CFOP，配套自编手册）
  ('cube-speed', 'CFOP 总览与配色方案', '理解 CFOP 四阶段的结构，固定自己的配色方案', E'1. 讲解 Cross → F2L → OLL → PLL 的整体结构。\n2. 确定并固定配色方案（一般白底、黄顶）。\n3. 测试当前复原成绩，作为提速起点。', '—', '记录当前平均成绩（3 次取平均）', 1, 60),
  ('cube-speed', 'Cross 十字：预判与效率', '在 8 步内完成十字，并开始练习预判', E'1. 十字不是「先做一个再找下一个」，而是一次性规划四块。\n2. 练习观察 15 秒，闭眼完成十字。\n3. 目标：8 步以内完成，且不用反复调整。', '—', '完成 20 次十字，记录步数', 2, 60),
  ('cube-speed', 'F2L 基础：四大标准情况', '掌握《F2L 练习手册》中 F2L 40 / 41 与基本情况的处理', E'1. 理解 F2L = 同时归位角块与棱块。\n2. 学习四大基本标准情况。\n3. 用「转化」的思路：把陌生情况变成标准情况。', 'U R U'' R'' / U'' L'' U L', '对照手册完成 F2L 01-08 各 3 次', 3, 60),
  ('cube-speed', 'F2L 进阶：目标角块白色朝上', '掌握白色朝上类情况的处理', E'1. 识别特征点：目标角块白色面朝上。\n2. 按《F2L 练习手册》分类逐条练习。\n3. 记录容易混淆的情况，课后重点巩固。', 'R U R'' U'' R U R'' U'' R U R''', '手册 F2L 09-18 各 3 次', 4, 60),
  ('cube-speed', 'F2L 进阶：目标角块白色朝侧', '掌握白色朝侧类情况的处理', E'1. 识别特征点：目标角块白色面朝侧。\n2. 区分「角一棱二」「角一棱三」的不同处理。\n3. 练习整体观察，避免只盯一块。', 'R U'' R'' U R U'' R''', '手册 F2L 19-32 各 3 次', 5, 60),
  ('cube-speed', 'F2L 综合：角块在底层的处理', '能处理角块已落入底层但位置错误的疑难情况', E'1. 先用公式把错误的角块「请」到顶层。\n2. 再按标准情况处理。\n3. 练习：从打乱状态直接完成前两层。', 'R U R'' U''（顶出后再还原）', '完成 10 次前两层，记录用时', 6, 60),
  ('cube-speed', 'OLL 分类与识别方法', '掌握 OLL 的 5 大类与识别步骤', E'1. 按顶面黄色块分布分为十字、一字、拐角、单点、L 型五大类。\n2. 学习《OLL 练习手册》的识别步骤：先看棱、再看角。\n3. 练习快速判断属于哪一类。', '—', '随机打乱 20 次，说出每次的 OLL 类型', 7, 60),
  ('cube-speed', 'OLL 常用公式（十字类）', '掌握所有棱块已复原、只需复原角块的情况', E'1. 练习 OLL 21-27 等常用情况。\n2. 注意起手姿势与换手次数。\n3. 对照手册的「类似情况」提示，避免混淆。', 'R U2 R'' U'' R U R'' U'' R U'' R''', '手册十字类公式各 5 次', 8, 60),
  ('cube-speed', 'OLL 常用公式（一字与拐角类）', '掌握一字型与拐角型情况的处理', E'1. 一字型与拐角型的区分要点。\n2. 逐条练习对应公式。\n3. 强化手法连贯性，减少中间停顿。', 'F R U R'' U'' F'' 系列变体', '手册一字与拐角类各 5 次', 9, 60),
  ('cube-speed', 'PLL 棱换与角换', '掌握《PLL 合集》中的棱换与角换公式', E'1. 棱换：Ua、Ub、H、Z。\n2. 角换：Aa、Ab、E。\n3. 先辨认「哪条边已完整」，再决定用哪个公式。', 'R U'' R U R U R U'' R'' U'' R2', '手册棱换与角换公式各 5 次', 10, 60),
  ('cube-speed', 'PLL 综合与公式串联', '把 OLL 与 PLL 串成完整流程，减少中间观察时间', E'1. 复习全部已学 PLL 公式。\n2. 练习从 OLL 结束状态直接进入 PLL 的衔接。\n3. 目标：完成一次复原的观察停顿不超过 2 次。', '综合', '完成 10 次完整复原，记录平均', 11, 60),
  ('cube-speed', '手法连贯训练与全流程模拟', '提升手法速度与连贯性，完成结课测评', E'1. 手法优化：减少换手、避免整层搬运。\n2. 用专业计时器进行模拟赛。\n3. 结课测评：12 次去掉最好最差后取平均。', '综合', '每天 12 次复原，记录成绩曲线', 12, 60),

  -- 高阶魔方
  ('cube-high-order', '四阶魔方与降阶思路', '理解降阶法：先把四阶变成三阶，再按三阶复原', E'1. 认识四阶的结构（无固定中心块）。\n2. 讲解降阶法三个步骤：合并中心 → 配对棱块 → 按三阶复原。\n3. 明确四阶与三阶的关键差异。', '—', '说出降阶法的三个步骤', 1, 60),
  ('cube-high-order', '四阶中心块合并', '独立完成六个面的中心块合并', E'1. 按固定顺序合并（如先白后黄）。\n2. 学习「条」的拼接方法。\n3. 注意保持已合并的面不被破坏。', 'Uw / Rw 系列', '完成 5 次四阶中心块合并', 2, 60),
  ('cube-high-order', '四阶棱块配对', '完成十二组棱块的配对', E'1. 用「翻棱」方法把两个同色棱块拼到一起。\n2. 处理最后一组棱时的特殊情况。\n3. 检查是否全部配对完成。', 'Uw'' R U R'' F R'' F'' R Uw', '完成 5 次棱块配对', 3, 60),
  ('cube-high-order', '四阶奇偶校验处理', '识别并修正降阶后出现的两种特殊情况', E'1. OLL 奇偶：顶层单棱翻转。\n2. PLL 奇偶：最后两棱互换。\n3. 记住两个专用公式并反复练习。', 'r2 U2 r2 Uw2 r2 Uw2', '各练习 10 次奇偶公式', 4, 60),
  ('cube-high-order', '五阶魔方复原', '把四阶经验迁移到五阶，独立完成复原', E'1. 五阶中心块的特点与合并技巧。\n2. 棱块配对与四阶的异同。\n3. 完整复原一次五阶。', '3Uw / 3Rw 系列', '独立完成五阶复原 1 次', 5, 60),
  ('cube-high-order', '高阶专项练习与测评', '提升高阶复原效率，完成阶段测评', E'1. 集中练习最耗时的环节。\n2. 记录四阶、五阶的最好成绩。\n3. 阶段测评并制定下一步计划。', '综合', '每天完成 3 次四阶复原', 6, 60),

  -- 赛事主流魔方
  ('cube-competition', 'WCA 赛事与比赛项目', '了解官方赛事体系与主流比赛项目', E'1. WCA 是什么：官方赛事组织与成绩认证。\n2. 常见项目：三阶、二阶、四阶、金字塔、单手、盲拧等。\n3. 认识比赛使用的专业设备与计时器。', '—', '说出 3 个 WCA 比赛项目', 1, 60),
  ('cube-competition', '比赛规则与流程', '掌握检录、观察、计时、判罚等完整流程', E'1. 比赛当天的完整流程。\n2. 观察时间（15 秒）的规则与超时判罚。\n3. 常见犯规情况与成绩判定方式。', '—', '模拟一次完整比赛流程', 2, 60),
  ('cube-competition', '打乱与成绩计算', '理解官方打乱规则与成绩统计方式', E'1. 打乱是如何生成与保密的。\n2. 平均成绩的计算方式（去掉最好最差）。\n3. 练习按规则记录自己的成绩。', '—', '记录 5 次成绩并算出平均值', 3, 60),
  ('cube-competition', '赛前热身与心态调整', '建立适合自己的赛前准备流程', E'1. 赛前热身的目的：让手法进入状态，而不是临时提速。\n2. 呼吸与注意力聚焦方法。\n3. 制定个人的赛前 10 分钟流程。', '—', '写出自己的赛前准备清单', 4, 60),
  ('cube-competition', '失误处理与赛后复盘', '学会在失误后快速调整，并完成结构化复盘', E'1. 失误后的常见反应与代价。\n2. 如何在剩余次数中调整目标（保护平均成绩）。\n3. 复盘模板：成绩、失误点、下次改进项。', '—', '针对一次模拟赛写复盘', 5, 60),
  ('cube-competition', '模拟赛与结课测评', '完整参加一次模拟赛，达到稳定发挥的目标', E'1. 按正式流程进行模拟赛（含检录、观察、计时）。\n2. 记录全部成绩并计算平均。\n3. 结课总结与下一阶段目标设定。', '综合', '参加一次真实或模拟赛事', 6, 60),

  -- 盲拧专项魔方
  ('cube-blindfold', '盲拧原理与记忆流程', '理解盲拧的三个阶段：观察编码 → 记忆 → 闭眼执行', E'1. 盲拧不是「看着记」，而是把状态转成操作序列。\n2. 三阶段流程讲解。\n3. 明确训练重点在编码与记忆，而不是手法速度。', '—', '说出盲拧的三个阶段', 1, 60),
  ('cube-blindfold', '编码体系：给每个块一个名字', '建立自己的角块与棱块编码方案', E'1. 角块编码：给 8 个角块各分配一个字母或数字。\n2. 棱块编码：给 12 个棱块分配编码。\n3. 熟记编码，做到看到位置就能说出代号。', '—', '默写自己的完整编码表', 2, 60),
  ('cube-blindfold', '从状态到字母串', '能把打乱状态转换成可执行的操作序列', E'1. 按固定顺序（如从缓冲块出发）逐个读出编码。\n2. 把编码串接成完整的字母串。\n3. 用简单打乱练习转换，先不要求闭眼。', '—', '把 5 个简单打乱写成字母串', 3, 60),
  ('cube-blindfold', '记忆方法训练', '把字母串转化为易记的图像或故事', E'1. 为什么纯字母串记不住：短期记忆容量有限。\n2. 图像编码法：每两个字母组合成一个画面。\n3. 练习用画面串联记忆，逐步延长长度。', '—', '用图像法记住 6 个字母的串', 4, 60),
  ('cube-blindfold', '闭眼执行与常见中断处理', '能在闭眼状态下完成完整复原流程', E'1. 睁眼确认开头几步，再闭眼执行。\n2. 中途忘记时的应对：回到安全点重新确认。\n3. 逐步减少睁眼次数，直到完全闭眼。', '—', '尝试完成一次完整盲拧（可允许中途重来）', 5, 60),
  ('cube-blindfold', '盲拧综合与结课测评', '独立完成一次完整盲拧复原', E'1. 全流程串讲与薄弱环节强化。\n2. 结课测评：独立完成一次盲拧。\n3. 记录用时，并制定后续练习计划。', '综合', '每周练习 5 次盲拧并记录成功率', 6, 60),

  -- 桌游初级课程
  ('board-basic', '认识桌游：规则也是游戏的一部分', '理解「规则先行」，能完整听完规则再开始', E'1. 桌游和玩具的区别：有明确规则与胜负判定。\n2. 学习完整听规则的方法：先听目标、再听做法、最后确认限制。\n3. 用一款简单桌游实践「先听完再动手」。', '—', '回家给家人复述今天学的规则', 1, 60),
  ('board-basic', '我的回合我做主：独立决策', '在回合中独立做出选择，不依赖他人提示', E'1. 每个回合的决策结构：我能做什么 → 我想做什么 → 会有什么后果。\n2. 游戏练习，老师不提示答案，只在结束后复盘。\n3. 强调：没有标准答案，但要能说清理由。', '—', '记录自己今天做过的三个决定', 2, 60),
  ('board-basic', '行动之前先想一想', '在动手前先规划，减少盲目行动', E'1. 训练「先观察、再计划、后行动」的顺序。\n2. 用一款需要资源积累的游戏练习提前规划。\n3. 对比：有计划的一轮和没计划的一轮，结果差在哪里。', '—', '下次游戏前先说出自己的计划', 3, 60),
  ('board-basic', '看懂了什么，才能做什么', '学会从局面中提取关键信息', E'1. 观察训练：说出当前局面最重要的三条信息。\n2. 区分「看起来重要」和「真的重要」。\n3. 练习据此调整自己的行动。', '—', '游戏结束后说出胜负的关键点', 4, 60),
  ('board-basic', '为什么会赢，为什么会输', '能用完整句子做游戏复盘，归纳得失', E'1. 复盘三问：我做了什么？结果如何？下次怎么改？\n2. 用「因为……所以……」组织语言。\n3. 学会听别人复盘并提出自己的看法。', '—', '写一句话复盘今天最喜欢的一局', 5, 60),
  ('board-basic', '我的第一场小小邀请赛', '综合运用所学，完整体验一场比赛', E'1. 讲解比赛礼仪与轮次安排。\n2. 进行多轮比赛，记录胜负。\n3. 结课复盘：这段时间自己最大的变化是什么。', '综合', '邀请好朋友一起玩一次桌游', 6, 60),

  -- 桌游中级课程
  ('board-mid', '从个人到团队：合作型桌游', '理解合作目标与个人目标的区别', E'1. 合作型桌游的胜负判定：大家一起赢或一起输。\n2. 体验信息共享的重要性与风险。\n3. 讨论：什么时候该说出来，什么时候该保留。', '—', '说出一次合作的失败原因', 1, 60),
  ('board-mid', '分工与角色：谁该做什么', '学会根据能力与局势分配任务', E'1. 认识团队中的不同角色。\n2. 练习开局前的分工讨论。\n3. 游戏中根据变化调整分工。', '—', '为本组设计一套分工方案', 2, 60),
  ('board-mid', '概率的直觉：这样做划算吗', '建立对概率与期望值的初步感觉', E'1. 用掷骰与抽牌体会「可能性大小」。\n2. 期望值直觉：收益 × 可能性，而不是只看最大收益。\n3. 在游戏中比较两个选择的长期收益。', '—', '记录一次「高风险高回报」的选择结果', 3, 60),
  ('board-mid', '多想一步：推理与预判', '能根据对手的行动推测其意图', E'1. 观察对手的选择，反推他需要什么。\n2. 练习「如果他这样做，我该怎么办」。\n3. 尝试提前两步做规划。', '—', '在游戏中预测对手下一步的意图', 4, 60),
  ('board-mid', '整局规划：从开局想到收官', '为自己的整局制定阶段性目标', E'1. 把一局游戏拆成开局、中盘、收官。\n2. 每个阶段的目标与资源分配。\n3. 练习根据局势调整目标，而不是死守原计划。', '—', '写出一局的阶段目标', 5, 60),
  ('board-mid', '沟通与协商：谈判也是能力', '在需要协商的游戏中达成有利约定', E'1. 谈判前的准备：我有什么、我要什么、对方缺什么。\n2. 提出方案与让步的节奏。\n3. 练习遵守约定并承担后果。', '—', '完成一次成功的交易或约定', 6, 60),

  -- 桌游高级课程
  ('board-high', '模拟现实：桌游里的社会缩影', '理解模拟经营类桌游与现实决策的对应关系', E'1. 讲解模拟经营类桌游的设计逻辑。\n2. 对应现实概念：资源、成本、收益、风险。\n3. 明确本阶段的学习目标：做出有依据的决策。', '—', '说出游戏中三个对应现实的设定', 1, 90),
  ('board-high', '人力资源配置', '根据目标与成本决定投入哪些资源', E'1. 资源有限时的取舍原则。\n2. 短期收益与长期布局的权衡。\n3. 练习：为自己的策略配置资源并说明理由。', '—', '为下一局写一份资源配置计划', 2, 90),
  ('board-high', '现金流与投资概念', '理解现金流与投资回报的基本逻辑', E'1. 什么是现金流：进出账的时间差为什么重要。\n2. 投资回报：投入多久能收回，风险在哪里。\n3. 在游戏中体验「资金链断裂」的后果。', '—', '记录一局的收支变化', 3, 90),
  ('board-high', '叠加交易计算', '能计算多步骤交易的综合收益', E'1. 一笔交易涉及多个步骤时的收益计算。\n2. 警惕「看起来赚了但其实亏了」的陷阱。\n3. 练习用纸笔辅助计算复杂交易。', '—', '算清一笔三步交易的净收益', 4, 90),
  ('board-high', '评判性思维：质疑信息与规则', '学会质疑局面中的假设，不盲从他人判断', E'1. 信息可能不完整，甚至被刻意误导。\n2. 训练区分事实与推测。\n3. 练习提出有依据的质疑。', '—', '针对一次判断提出自己的反例', 5, 90),
  ('board-high', '宏观判断与结课测评', '在复杂局势中做出整体判断并承担结果', E'1. 从全局视角评估局势：谁领先、我该做什么。\n2. 综合运用本阶段全部概念完成一局比赛。\n3. 结课复盘与阶段性评价。', '综合', '独立完成一局完整模拟经营游戏并复盘', 6, 90)
) as v(slug, title, goal, content, formula, homework, order_index, duration_minutes)
join public.courses c on c.slug = v.slug
where not exists (select 1 from public.course_lessons cl where cl.course_id = c.id);

-- -----------------------------------------------------------------------------
-- 2. 师资团队（依据宣传册「师资优势」整理）
-- -----------------------------------------------------------------------------
insert into public.coaches (name, title, years_competing, years_teaching, avg_time, highlights, bio, sort_order, is_active)
select v.name, v.title, v.years_competing, v.years_teaching, v.avg_time, v.highlights, v.bio, v.sort_order, true
from (values
  ('蔡林成', '魔方 · 桌游教练', '9 年', '7 年', '9s',
   array['9 年魔方竞技生涯', '7 年魔方与桌游课程教学经验', '多家学校合作委任魔方、桌游老师'],
   '长期负责学校社团与机构常规课程，擅长把复杂的还原逻辑拆成孩子能听懂的小步骤。', 10),
  ('李国聪', '盲拧 · 竞速教练', '8 年', null, '10s',
   array['专项魔方吉尼斯世界纪录获得者', '竞技叠杯接力项目亚洲纪录保持者', '2018 WCA 南宁赛三盲冠军'],
   '在盲拧与竞速项目上具备顶级竞技经验，负责高阶学员的专项突破训练。', 20),
  ('蔡嘉成', '器材调试 · 手法教研', '20 场赛事', null, '9s / 四阶 30s',
   array['专业魔方调试与改磁', '曾为多名国内顶尖选手测试改进魔方', '专业竞速手法教研'],
   '负责魔方器材调校与竞速手法教研，为教学体系提供手法标准与器材支持。', 30),
  ('郑喆', '高阶 · 单手教练', '17 年四阶', null, '10s / 单手 18s',
   array['四阶项目水平达深圳第一', '2018 WCA 揭阳赛三阶女子组第一', '三阶单手复原平均 18s'],
   '在高阶与单手项目上有深厚积累，负责高阶课程的进阶指导。', 40),
  ('柯陈飞', '魔方 · 桌游教练', '10 年', '7 年', '10s',
   array['10 年魔方竞技生涯', '7 年魔方与桌游课程教学经验', '官方赛事奖牌 28 枚'],
   '兼具魔方与桌游两条课程线的教学经验，擅长带班与课堂节奏把控。', 50),
  ('李澳', '竞速教练', '7 年', null, null,
   array['7 年魔方竞技生涯'],
   '专注竞速项目训练，负责学员的手法打磨与成绩跟进。', 60)
) as v(name, title, years_competing, years_teaching, avg_time, highlights, bio, sort_order)
where not exists (select 1 from public.coaches co where co.name = v.name);
